    return `<button class="tab${k===tab?" on":""}" data-tab="${k}">${l}<span class="n">${n}</span></button>`;
  }).join("");

  if (tab === "products") { renderProducts(); updateSelbar(); return; }
  // list
  const q = $("#q").value.trim().toLowerCase();
  const rows = orders.filter(inTab).filter(o => !q || [o.customer.name,o.customer.phone,o.shopifyName,o.id,o.customer.city].join(" ").toLowerCase().includes(q));
  lastRows = rows;
  $("#list").innerHTML = rows.length ? rows.map(card).join("") : `<div class="empty">No orders here yet.</div>`;
  updateSelbar();
}

