let pending = 0;
async function patch(id, body){
  pending++;
  try {
    const d = await api("/api/orders/"+encodeURIComponent(id), {method:"PATCH", body:JSON.stringify(body)});
    if (d.order){ const i = orders.findIndex(o=>o.id===id); if (i >= 0) orders[i] = {...d.order, _fresh: orders[i]._fresh}; }
    return d;
  } finally { pending--; }
}
// instant update on screen, saved in the background; undo if the save fails
function quick(id, change, body){
  const o = orders.find(x=>x.id===id); if (!o) return;
  const before = {status:o.status, calls:o.calls};
  change(o); render();
  patch(id, body).then(()=>{ if (!pending) render(); }).catch(()=>{ Object.assign(o, before); render(); openModal("<p>❌ Pas enregistré (connexion). Réessayez.</p>"); });
}

$("#tabs").onclick = e => { const b=e.target.closest("[data-tab]"); if(!b) return; tab=b.dataset.tab; try{localStorage.setItem("ordersTab",tab)}catch(e){}; render(); };
$("#q").oninput = render;
$("#list").onclick = async e => {
  const cb = e.target.closest("[data-sel]");
  if (cb) { cb.checked ? selected.add(cb.dataset.sel) : selected.delete(cb.dataset.sel); updateSelbar(); return; }
  const art = e.target.closest(".order"); if(!art) return;
  const id = art.dataset.id;
  const sb = e.target.closest("[data-status]");
  if (sb) { const s = sb.dataset.status; quick(id, o=>{ o.status = s; }, {status:s}); return; }
  if (e.target.closest("[data-act=call]")) { quick(id, o=>{ o.calls = (o.calls||0)+1; }, {addCall:true}); return; }
  const fb = e.target.closest("[data-act=fiabilo]");
  if (fb) {
    if (!fb.dataset.sure) { fb.dataset.sure = "1"; fb.textContent = "Cliquez encore pour confirmer l'envoi"; return; }
    fb.disabled = true; fb.textContent = "Envoi à Fiabilo…";
    const r = await gfetch("/api/orders/"+encodeURIComponent(id)+"/fiabilo", {method:"POST", headers:{authorization:"Bearer "+token}});
    const d = await r.json();
    if (!r.ok) { openModal(`<h3 style="margin:0">❌ Fiabilo</h3><pre>${esc(d.error||"Erreur")}</pre>`); fb.disabled=false; fb.textContent="🚚 Envoyer à Fiabilo"; delete fb.dataset.sure; return; }
    openModal(`<h3 style="margin:0">✅ Colis créé chez Fiabilo</h3><p>Code : <b>${esc(d.code)}</b></p>`);
    await load();
  }
};
$("#list").addEventListener("change", async e => {
