function thumbUrl(u){ if(!u) return ""; if(u.startsWith("//")) u = "https:"+u; return u + (u.includes("?")?"&":"?") + "width=160"; }
function pilot(){
  const sel = orders.filter(o=>selected.has(o.id));
  const groups = new Map(); let pieces = 0, cash = 0;
  sel.forEach(o => { cash += Number(o.total)||0; (o.items||[]).forEach(i => {
    pieces++;
    const key = String(i.variantId || i.title);
    const parts = String(i.title||"").split(" — ");
    const g = groups.get(key) || { title: parts[0], variant: parts.slice(1).join(" — "), image: i.image || "", count: 0, orders: [] };
    g.count++; if (!g.image && i.image) g.image = i.image;
    const num = o.shopifyName || o.id; if (!g.orders.includes(num)) g.orders.push(num);
    groups.set(key, g);
  }); });
  const list = [...groups.values()].sort((a,b)=> b.count-a.count || a.title.localeCompare(b.title));
  $("#pilotSub").textContent = `${sel.length} commande(s) · ${pieces} pièce(s)`;
  $("#pilotBody").innerHTML = `<div class="tiles"><div class="tile"><b>${pieces}</b><span>Pièces</span></div><div class="tile"><b>${list.length}</b><span>Modèles</span></div><div class="tile"><b>${sel.length}</b><span>Commandes</span></div></div>
    <div class="lbl">À sortir du stock</div>
    ${list.map(g=>`<div class="pk">${g.image?`<img src="${esc(thumbUrl(g.image))}" alt="">`:`<div class="ph">⌚</div>`}<div><div class="t">${esc(g.title)}</div>${g.variant?`<div class="v">${esc(g.variant)}</div>`:""}<div class="o">${g.orders.map(n=>"#"+esc(n)).join(", ")}</div></div><div class="q">×${g.count}</div></div>`).join("") || `<div class="empty">Aucune montre.</div>`}
    <p class="muted" style="margin-top:16px">Total à encaisser pour ces commandes : <b>${money(cash,"TND")}</b></p>`;
  $("#drawer").classList.add("on");
}
$("#pilotBtn").onclick = pilot;
