$("#exportBtn").onclick = () => {
  const rows = orders.filter(o=>o.status==="confirmed");
  if (!rows.length) { openModal("<p>No confirmed orders to export.</p>"); return; }
  const head = ["Order","Name","Phone","Governorate","City","Address","Products","Qty","Total (COD)","Notes"];
  const lines = rows.map(o=>[o.shopifyName||o.id,o.customer.name,o.customer.phone,o.customer.governorate,o.customer.city,o.customer.address,o.items.map(i=>i.title).join(" + "),o.items.length,o.total,o.notes]);
  const csv = "﻿"+[head,...lines].map(r=>r.map(v=>`"${String(v??"").replace(/"/g,'""')}"`).join(",")).join("\n");
  const a = document.createElement("a");
  a.href = URL.createObjectURL(new Blob([csv],{type:"text/csv"}));
  a.download = `confirmed-orders-${new Date().toISOString().slice(0,10)}.csv`; a.click();
};

